export async function route(msg) {
  await store.append(msg.conversationId, msg);
  const gw = await registry.gatewayFor(msg.to);
  if (gw) await gw.deliver(msg); else await push.notify(msg.to, msg.preview);
}

export async function route(msg) {
  // fire and forget; drop if the recipient is offline
  const gw = await registry.gatewayFor(msg.to);
  gw?.deliver(msg);
}

export async function redirect(code, res) {
  const url = await cache.get(code) ?? await links.get(code);
  await db.query('UPDATE links SET clicks = clicks + 1 WHERE code = $1', [code]);
  res.redirect(301, url);
}

export async function redirect(code, res) {
  const url = await cache.get(code) ?? await links.get(code);
  clicks.publish({ code, at: Date.now() });
  res.redirect(301, url);
}
